import React, { useEffect, useState } from 'react';
import { addDoc, collection, getDocs, deleteDoc, doc } from 'firebase/firestore';
import { db } from '../services/firebaseConfig';

export default function FixedExpenses() {
  const [fixedList, setFixedList] = useState([]);
  const [name, setName] = useState('');
  const [value, setValue] = useState('');

  const loadFixedExpenses = async () => {
    const snapshot = await getDocs(collection(db, 'fixed_expenses'));
    setFixedList(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
  };

  useEffect(() => {
    loadFixedExpenses();
  }, []);

  const addFixedExpense = async () => {
    if (!name || !value) return alert('Preencha os campos!');
    await addDoc(collection(db, 'fixed_expenses'), { name, value: parseFloat(value) });
    setName('');
    setValue('');
    loadFixedExpenses();
  };

  const removeFixed = async (id) => {
    await deleteDoc(doc(db, 'fixed_expenses', id));
    loadFixedExpenses();
  };

  return (
    <div className="p-6 text-white">
      <h2 className="text-2xl font-bold mb-4">💼 Gastos Fixos</h2>
      <div className="mb-4 flex gap-2">
        <input
          className="p-2 rounded bg-gray-800"
          placeholder="Nome do gasto"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          className="p-2 rounded bg-gray-800"
          placeholder="Valor"
          type="number"
          value={value}
          onChange={(e) => setValue(e.target.value)}
        />
        <button
          className="bg-green-600 px-4 py-2 rounded hover:bg-green-700"
          onClick={addFixedExpense}
        >
          Adicionar
        </button>
      </div>

      <ul className="space-y-2">
        {fixedList.map(item => (
          <li
            key={item.id}
            className="bg-gray-800 flex justify-between p-2 rounded"
          >
            <span>{item.name} — R$ {item.value.toFixed(2)}</span>
            <button
              className="text-red-500"
              onClick={() => removeFixed(item.id)}
            >
              Remover
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
